$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');if(!in_array($method,['GET','POST'],true)){http_response_code(405);exit;}$authz=(string)($_SERVER['HTTP_AUTHORIZATION']??'');$token='';if(str_starts_with($authz,'Bearer '))$token=trim(substr($authz,7));elseif(str_starts_with($authz,'DPoP '))$token=trim(substr($authz,5));try{if($token==='')throw new RuntimeException('invalid_token');$proof=$_SERVER['HTTP_DPOP']??null;$proof=is_string($proof)?$proof:null;$oauthProofs->validateResourceProof($token,$proof,$method,$jwt->issuer().'/oauth/userinfo');echo json_encode($oidc->userInfo($token),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}catch(Throwable $e){http_response_code(401);header('WWW-Authenticate: DPoP error="invalid_token"');echo json_encode(['error'=>'invalid_token'],JSON_THROW_ON_ERROR);}
